/* Software-in-the-loop test of the three components of battsim_master on the PC (stage B): the Embedded Coder code of
 * SupplyMonitor, BattSimMode and CellChannels together with the RTE generated by tools/rtegen, stimulated through the
 * RTE buffers, in the task order of rte.yaml (SupplyTask10ms, ModeTask10ms, CellTask10ms, every 10 ms).
 * CAN frames are packed and unpacked with the generated CanDb code, so the chain "setpoint frame -> duty" and
 * "buffers -> status frame" is checked with the real DBC layout; the RTE glue between the frame and the buffer
 * (RteConfig.cpp) is not part of this test.
 * Build and start: test_battsim_sil.py (tests list of the workspace, ci/tests.yaml). */

#include "CanDb.h"
#include "Rte_BattSimMode.h"
#include "Rte_CellChannels.h"
#include "Rte_Internal.h"
#include "Rte_SupplyMonitor.h"

#include <math.h>
#include <stdio.h>
#include <string.h>

static int failures = 0;
static int checks   = 0;

#define CHECK(cond)                                                            \
    do                                                                         \
    {                                                                          \
        ++checks;                                                              \
        if (!(cond))                                                           \
        {                                                                      \
            ++failures;                                                        \
            printf("  FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond);           \
        }                                                                      \
    } while (0)

/* BATTSIM_STATUS and friends (DBC value tables) */
enum
{
    STATUS_STANDBY = 1,
    STATUS_REMOTE  = 3,
    STATUS_FAIL    = 5,
    FAIL_NONE      = 0,
    FAIL_TIMEOUT   = 1,
    FAIL_ALIVE     = 2,
    FAIL_OVERLOAD  = 3,
    FAIL_WATCHDOG  = 4,
    ENABLE_ON      = 2,
    REMOTE_REMOTE  = 2,
    MODE_STANDBY   = 1,
    MODE_ON        = 2,
    OUTPUT_DISABLE = 1,
    OUTPUT_ENABLE  = 2
};

#define MODE(name)  Rte_Buf_BattSimMode_##name##_##name
#define CELL(name)  Rte_Buf_CellChannels_##name##_##name
#define SUPPLY(name) Rte_Buf_SupplyMonitor_##name##_##name

