/* one 10 ms step of the application task */
static void cycle(void)
{
    SupplyTask10ms();
    ModeTask10ms();
    CellTask10ms();
}

static void cycles(int n)
{
    for (int i = 0; i < n; ++i)
    {
        cycle();
    }
}

static void controlFrame(uint8 remote, uint8 mode, uint8 output)
{
    /* a valid 0x130, round trip through the generated pack/unpack of the DBC */
    CanDb_CONTROL_BATTSIM_t msg;
    CanDb_CONTROL_BATTSIM_Init(&msg);
    msg.BATTSIM_REMOTE_CONTROL = remote;
    msg.BATTSIM_MODE_CONTROL   = mode;
    msg.BATTSIM_OUTPUT_CONTROL = output;
    uint8_t data[CANDB_CONTROL_BATTSIM_LENGTH];
    CanDb_CONTROL_BATTSIM_Pack(&msg, data);
    CanDb_CONTROL_BATTSIM_t rx;
    CanDb_CONTROL_BATTSIM_Unpack(&rx, data);
    MODE(RemoteControl) = (uint8)rx.BATTSIM_REMOTE_CONTROL;
    MODE(ModeControl)   = (uint8)rx.BATTSIM_MODE_CONTROL;
    MODE(OutputControl) = (uint8)rx.BATTSIM_OUTPUT_CONTROL;
}

static void setpointFrame123(uint8 en1, double v1, uint8 en2, double v2, uint8 en3, double v3)
{
    CanDb_CONTROL_CELL01_02_03_t msg;
    CanDb_CONTROL_CELL01_02_03_Init(&msg);
    msg.CELL01_ENABLE      = en1;
    msg.CELL02_ENABLE      = en2;
    msg.CELL03_ENABLE      = en3;
    msg.CELL01_VOLTAGE_SET = CanDb_CONTROL_CELL01_02_03_CELL01_VOLTAGE_SET_FromDouble(v1);
    msg.CELL02_VOLTAGE_SET = CanDb_CONTROL_CELL01_02_03_CELL02_VOLTAGE_SET_FromDouble(v2);
    msg.CELL03_VOLTAGE_SET = CanDb_CONTROL_CELL01_02_03_CELL03_VOLTAGE_SET_FromDouble(v3);
    uint8_t data[CANDB_CONTROL_CELL01_02_03_LENGTH];
    CanDb_CONTROL_CELL01_02_03_Pack(&msg, data);
    CanDb_CONTROL_CELL01_02_03_t rx;
    CanDb_CONTROL_CELL01_02_03_Unpack(&rx, data);
    *voltSetIn[0] = (float32)CanDb_CONTROL_CELL01_02_03_CELL01_VOLTAGE_SET_ToDouble(rx.CELL01_VOLTAGE_SET);
    *voltSetIn[1] = (float32)CanDb_CONTROL_CELL01_02_03_CELL02_VOLTAGE_SET_ToDouble(rx.CELL02_VOLTAGE_SET);
    *voltSetIn[2] = (float32)CanDb_CONTROL_CELL01_02_03_CELL03_VOLTAGE_SET_ToDouble(rx.CELL03_VOLTAGE_SET);
    *enableIn[0]  = (uint8)rx.CELL01_ENABLE;
    *enableIn[1]  = (uint8)rx.CELL02_ENABLE;
    *enableIn[2]  = (uint8)rx.CELL03_ENABLE;
}

static int outputsOff(void)
{
    int off = (MODE(OutputEnable) == 0U);
    for (int k = 0; k < 14; ++k)
    {
        off = off && (*enOut[k] == 0U) && (*dutyOut[k] == 0U);
    }
    return off;
}

static void pressRemoteKey(void)
{
    MODE(BtnRemote) = 1U;
    cycles(4);
    MODE(BtnRemote) = 0U;
    cycles(4);
}

static void pressAllOnOffKey(void)
{
    MODE(BtnAllOnOff) = 1U;
    cycles(4);
    MODE(BtnAllOnOff) = 0U;
    cycles(4);
}

static void goToRun(void)
{
    controlFrame(REMOTE_REMOTE, MODE_ON, OUTPUT_DISABLE);
    cycles(2);
    controlFrame(REMOTE_REMOTE, MODE_ON, OUTPUT_ENABLE);
    cycles(2);
}

static void backToStandby(void)
{
    controlFrame(REMOTE_REMOTE, MODE_STANDBY, OUTPUT_DISABLE);
    cycles(2);
}

/* ---------------------------------------------------------------------------------------------------------------- */

static void startIsStandbyWithWatchdogReason(void)
{
    /* first call of the model: this start followed a watchdog reset (bsw.reset.watchdog + qualifier) */
    MODE(ResetWatchdog) = 1U;
    MODE(ResetQlf)      = QLF_OK;
    for (int i = 0; i < 9; ++i)
    {
        *controlQlf[i] = QLF_OK;
    }
    for (int k = 0; k < 14; ++k)
    {
        *adcQlfIn[k] = QLF_OK;
    }
    SUPPLY(ISupplyQlf) = QLF_OK;
    cycles(3);
    MODE(ResetWatchdog) = 0U;
    CHECK(MODE(BattSimStatus) == STATUS_STANDBY);
    CHECK(MODE(OutputStatus) == 1U);
    CHECK(MODE(FailReason) == FAIL_WATCHDOG);
    CHECK(outputsOff());
    CHECK(MODE(LedRemote) == 0U);
    CHECK(MODE(FwVersionMajor) == 0U && MODE(FwVersionMinor) == 2U && MODE(FwVersionPatch) == 0U);
    /* the held setpoints of the CAN buffers do not act in STANDBY (FW-16) */
    setpointFrame123(ENABLE_ON, 3.7, ENABLE_ON, 3.7, ENABLE_ON, 3.7);
    cycles(5);
    CHECK(outputsOff());
    /* the reason is shown until the first state change */
    controlFrame(REMOTE_REMOTE, MODE_ON, OUTPUT_DISABLE);
    cycles(2);
    CHECK(MODE(BattSimStatus) == STATUS_REMOTE);
    CHECK(MODE(FailReason) == FAIL_NONE);
    CHECK(MODE(LedRemote) == 1U);
    backToStandby();
    CHECK(MODE(BattSimStatus) == STATUS_STANDBY);
}

static void setpointFrameBecomesDuty(void)
{
    setpointFrame123(ENABLE_ON, 3.7, 0U, 4.0, ENABLE_ON, 5.5);
    goToRun();
    CHECK(MODE(BattSimStatus) == STATUS_REMOTE);
    CHECK(MODE(OutputStatus) == 2U);
    CHECK(MODE(OutputEnable) == 1U);
    /* 3.7 V: 0.570892 + 0.7 * (0.763797 - 0.570892) = 0.7059255 -> 7059 (0.01 %) */
    CHECK(*dutyOut[0] == 7059U);
    CHECK(*enOut[0] == 1U);
    CHECK(*stateOut[0] == 2U);
    /* channel 2 is not enabled: no ENABLE, status disabled; the PWM follows its setpoint like the old firmware */
    CHECK(*enOut[1] == 0U);
    CHECK(*stateOut[1] == 1U);
    CHECK(*dutyOut[1] == 7638U);
    /* channel 3: 5.5 V is above the limit of 5.0 V: duty of 5.0 V (0.9566), status "setpoint error" */
    CHECK(*dutyOut[2] == 9566U);
    CHECK(*stateOut[2] == 3U);
    CHECK(*enOut[2] == 1U);
    /* setpoint 0 V, 5 V and the table nodes */
    setpointFrame123(ENABLE_ON, 0.0, ENABLE_ON, 5.0, ENABLE_ON, 1.0);
    cycle();
    CHECK(*dutyOut[0] == 0U);
    CHECK(*dutyOut[1] == 9566U);
    CHECK(*dutyOut[2] == 1859U); /* 0.185875 -> 1858.75 -> 1859 */
    /* the set values of the other groups of cells are 0 V and not enabled */
    CHECK(*dutyOut[5] == 0U && *enOut[5] == 0U);
    /* OUTPUT=1 switches the PWM off at once, the setpoints stay */
    controlFrame(REMOTE_REMOTE, MODE_ON, OUTPUT_DISABLE);
    cycle();
    CHECK(outputsOff());
    CHECK(MODE(BattSimStatus) == STATUS_REMOTE);
    CHECK(MODE(OutputStatus) == 1U);
    controlFrame(REMOTE_REMOTE, MODE_ON, OUTPUT_ENABLE);
    cycle();
    CHECK(*dutyOut[1] == 9566U);
    backToStandby();
    CHECK(outputsOff());
    CHECK(MODE(BattSimStatus) == STATUS_STANDBY);
    /* an enable value of 1 ("disable" in the DBC) does not release a channel */
    setpointFrame123(1U, 3.0, 3U, 3.0, ENABLE_ON, 3.0);
    goToRun();
    CHECK(*enOut[0] == 0U && *enOut[1] == 0U && *enOut[2] == 1U);
    backToStandby();
}

static void actualValueFollowsTheMeasurement(void)
{
    /* 3.7 V at the cell: counts 2391 + 0.7 * 801 = 2951.7 of 4095 at 2048 mV -> about 1476 mV at the pin */
    for (int k = 0; k < 14; ++k)
    {
        *adcIn[k] = 1476U;
    }
    cycles(300);
    CHECK(fabsf(CELL(Cell01VoltAct_V) - 3.7f) < 0.01f);
    CHECK(fabsf(CELL(Cell14VoltAct_V) - 3.7f) < 0.01f);
    /* a sample with an invalid qualifier is ignored */
    *adcIn[0]    = 0U;
    *adcQlfIn[0] = QLF_ERROR_RANGE;
    cycles(300);
    CHECK(fabsf(CELL(Cell01VoltAct_V) - 3.7f) < 0.01f);
    *adcQlfIn[0] = QLF_OK;
    cycles(500);
    CHECK(CELL(Cell01VoltAct_V) < 0.05f);
    /* status frame of cells 1..3 with the generated pack code */
    CanDb_STATUS_CELL01_02_03_t msg;
    CanDb_STATUS_CELL01_02_03_Init(&msg);
    msg.CELL02_VOLTAGE_ACT = CanDb_STATUS_CELL01_02_03_CELL02_VOLTAGE_ACT_FromDouble(CELL(Cell02VoltAct_V));
    msg.CELL02_STATUS      = *stateOut[1];
    uint8_t data[CANDB_STATUS_CELL01_02_03_LENGTH];
    CanDb_STATUS_CELL01_02_03_Pack(&msg, data);
    CanDb_STATUS_CELL01_02_03_t rx;
    CanDb_STATUS_CELL01_02_03_Unpack(&rx, data);
    CHECK(fabs(CanDb_STATUS_CELL01_02_03_CELL02_VOLTAGE_ACT_ToDouble(rx.CELL02_VOLTAGE_ACT) - 3.7) < 0.01);
    /* the channels 15 and 16 are not fitted */
    CHECK(CELL(Cell15State) == 1U && CELL(Cell16State) == 1U);
    CHECK(CELL(Cell15VoltAct_V) == 0.0f && CELL(Cell16VoltAct_V) == 0.0f);
    for (int k = 0; k < 14; ++k)
    {
        *adcIn[k] = 0U;
    }
}

static void timeoutOfControlMessageSwitchesOffInTheSameStep(void)
{
    /* the RTE reports the timeout of 0x130 after 3 cycles of 100 ms; the DBC carries 300 ms */
    CHECK(CANDB_CONTROL_BATTSIM_CYCLE_MS == 100U);
    CHECK(CANDB_CONTROL_BATTSIM_TIMEOUT_MS == 300U);
    setpointFrame123(ENABLE_ON, 3.7, ENABLE_ON, 3.7, ENABLE_ON, 3.7);
    goToRun();
    CHECK(*enOut[0] == 1U && *dutyOut[0] != 0U);
    *controlQlf[6] = QLF_ERROR_TIMEOUT;
    cycle(); /* one 10 ms step: model, outputs and status in the same step */
    CHECK(MODE(BattSimStatus) == STATUS_FAIL);
    CHECK(MODE(FailReason) == FAIL_TIMEOUT);
    CHECK(MODE(OutputStatus) == 1U);
    CHECK(outputsOff());
    /* FAIL is latched: the message coming back does not restart anything */
    *controlQlf[6] = QLF_OK;
    controlFrame(REMOTE_REMOTE, MODE_ON, OUTPUT_ENABLE);
    cycles(5);
    CHECK(MODE(BattSimStatus) == STATUS_FAIL);
    CHECK(outputsOff());
    /* reset by command: REMOTE=2, MODE=1 */
    controlFrame(REMOTE_REMOTE, MODE_STANDBY, OUTPUT_DISABLE);
    cycle();
    CHECK(MODE(BattSimStatus) == STATUS_STANDBY);
    CHECK(MODE(FailReason) == FAIL_NONE);
}

static void aliveErrorSwitchesOffAfterDebounce(void)
{
    setpointFrame123(ENABLE_ON, 3.7, ENABLE_ON, 3.7, ENABLE_ON, 3.7);
    goToRun();
    /* an alive fault being debounced (QLF_DEBOUNCE) does not switch off */
    *controlQlf[6] = QLF_DEBOUNCE;
    cycles(5);
    CHECK(MODE(BattSimStatus) == STATUS_REMOTE);
    CHECK(MODE(OutputEnable) == 1U);
    /* QLF_OK again heals it */
    *controlQlf[6] = QLF_OK;
    cycles(2);
    CHECK(MODE(BattSimStatus) == STATUS_REMOTE);
    /* the debounce time is over: QLF_ERROR_ALIVE */
    *controlQlf[6] = QLF_ERROR_ALIVE;
    cycle();
    CHECK(MODE(BattSimStatus) == STATUS_FAIL);
    CHECK(MODE(FailReason) == FAIL_ALIVE);
    CHECK(outputsOff());
    *controlQlf[6] = QLF_OK;
    controlFrame(REMOTE_REMOTE, MODE_STANDBY, OUTPUT_DISABLE);
    cycle();
    CHECK(MODE(BattSimStatus) == STATUS_STANDBY);
}

static void lostControlMessageInStopIsNoFail(void)
{
    controlFrame(REMOTE_REMOTE, MODE_ON, OUTPUT_DISABLE);
    cycles(2);
    CHECK(MODE(BattSimStatus) == STATUS_REMOTE);
    *controlQlf[6] = QLF_ERROR_TIMEOUT;
    cycles(50);
    CHECK(MODE(BattSimStatus) == STATUS_REMOTE); /* as before: STOP stays */
    CHECK(MODE(OutputStatus) == 1U);
    /* an invalid 0x130 is REMOTE=3, MODE=7, OUTPUT=3: nothing is accepted, not even OUTPUT=2 */
    MODE(OutputControl) = OUTPUT_ENABLE;
    cycles(3);
    CHECK(MODE(OutputEnable) == 0U);
    backToStandby();
    CHECK(MODE(BattSimStatus) == STATUS_REMOTE); /* invalid: also no command back to STANDBY */
    *controlQlf[6] = QLF_OK;
    backToStandby();
    CHECK(MODE(BattSimStatus) == STATUS_STANDBY);
}

static void overloadIsFailAndNeedsLowCurrentToReset(void)
{
    setpointFrame123(ENABLE_ON, 3.7, ENABLE_ON, 3.7, ENABLE_ON, 3.7);
    goToRun();
    SUPPLY(ISupply_mV) = 1500U; /* 1.5 A at 1 V per A */
    cycles(150);
    CHECK(MODE(BattSimStatus) == STATUS_REMOTE);
    CHECK(SUPPLY(Overload) == 0U);
    cycles(130); /* 1.28 A are reached after about 245 cycles (time constant 1.28 s) */
    CHECK(SUPPLY(Overload) == 1U);
    CHECK(MODE(BattSimStatus) == STATUS_FAIL);
    CHECK(MODE(FailReason) == FAIL_OVERLOAD);
    CHECK(outputsOff());
    /* a reset command with the current still high is refused (the overload condition is still active) */
    backToStandby();
    CHECK(MODE(BattSimStatus) == STATUS_FAIL);
    SUPPLY(ISupply_mV) = 0U;
    cycles(20); /* about 1.28 A: the hysteresis keeps the condition above 1.08 A */
    CHECK(SUPPLY(Overload) == 1U);
    backToStandby();
    CHECK(MODE(BattSimStatus) == STATUS_FAIL);
    controlFrame(REMOTE_REMOTE, MODE_ON, OUTPUT_DISABLE); /* the reset command is gone */
    cycles(60);
    CHECK(SUPPLY(Overload) == 0U);
    CHECK(MODE(BattSimStatus) == STATUS_FAIL); /* still latched until it is reset */
    backToStandby();
    CHECK(MODE(BattSimStatus) == STATUS_STANDBY);
    CHECK(MODE(FailReason) == FAIL_NONE);
    /* supply current value for 0x121 and the LIMIT line */
    SUPPLY(ISupply_mV) = 1000U;
    SUPPLY(Limit)      = 1U;
    cycles(1000);
    CHECK(fabsf(SUPPLY(SupplyCurrent_A) - 1.0f) < 0.01f);
    CHECK(SUPPLY(LimitActive) == 1U);
    SUPPLY(ISupply_mV) = 0U;
    SUPPLY(Limit)      = 0U;
    cycles(1000);
    CHECK(SUPPLY(LimitActive) == 0U);
}

static void keysSwitchTheModes(void)
{
    controlFrame(0U, 0U, 0U); /* 0x130 without a command: REMOTE, MODE and OUTPUT "no signal" */
    cycles(2);
    CHECK(MODE(BattSimStatus) == STATUS_STANDBY);
    /* a bounce shorter than the debounce time is nothing */
    MODE(BtnRemote) = 1U;
    cycles(2);
    MODE(BtnRemote) = 0U;
    cycles(5);
    CHECK(MODE(BattSimStatus) == STATUS_STANDBY);
    /* REMOTE key: STANDBY -> REMOTE/STOP -> STANDBY */
    pressRemoteKey();
    CHECK(MODE(BattSimStatus) == STATUS_REMOTE);
    CHECK(MODE(LedRemote) == 1U);
    pressRemoteKey();
    CHECK(MODE(BattSimStatus) == STATUS_STANDBY);
    CHECK(MODE(LedRemote) == 0U);
    /* ALL ON/OFF in STANDBY: nothing (hand mode comes with stage D) */
    pressAllOnOffKey();
    CHECK(MODE(BattSimStatus) == STATUS_STANDBY);
    /* ALL ON/OFF in RUN: output off, it stays off until OUTPUT has left 2 */
    setpointFrame123(ENABLE_ON, 3.7, ENABLE_ON, 3.7, ENABLE_ON, 3.7);
    goToRun();
    CHECK(MODE(OutputEnable) == 1U);
    pressAllOnOffKey();
    CHECK(MODE(OutputEnable) == 0U);
    CHECK(MODE(BattSimStatus) == STATUS_REMOTE);
    cycles(5);
    CHECK(MODE(OutputEnable) == 0U); /* the CAN command OUTPUT=2 is still there */
    controlFrame(REMOTE_REMOTE, MODE_ON, OUTPUT_DISABLE);
    cycles(2);
    controlFrame(REMOTE_REMOTE, MODE_ON, OUTPUT_ENABLE);
    cycles(2);
    CHECK(MODE(OutputEnable) == 1U);
    /* ALL ON/OFF resets FAIL */
    *controlQlf[6] = QLF_ERROR_TIMEOUT;
    cycle();
    CHECK(MODE(BattSimStatus) == STATUS_FAIL);
    *controlQlf[6] = QLF_OK;
    controlFrame(0U, 0U, 0U);
    pressAllOnOffKey();
    CHECK(MODE(BattSimStatus) == STATUS_STANDBY);
    CHECK(MODE(FailReason) == FAIL_NONE);
}

static void remoteLedBlinksInFail(void)
{
    setpointFrame123(ENABLE_ON, 3.7, ENABLE_ON, 3.7, ENABLE_ON, 3.7);
    goToRun();
    *controlQlf[6] = QLF_ERROR_TIMEOUT;
    cycle();
    CHECK(MODE(BattSimStatus) == STATUS_FAIL);
    int edges = 0;
    int on    = 0;
    int last  = MODE(LedRemote);
    for (int i = 0; i < 80; ++i)
    {
        cycle();
        if (MODE(LedRemote) != last)
        {
            ++edges;
            last = MODE(LedRemote);
        }
        on += MODE(LedRemote);
    }
    CHECK(edges >= 3 && edges <= 5); /* 200 ms on, 200 ms off */
    CHECK(on >= 35 && on <= 45);
    *controlQlf[6] = QLF_OK;
    backToStandby();
}

static void aliveCountsOneToFourteen(void)
{
    uint8 previous = *aliveOut[0];
    int   steps    = 0;
    for (int i = 0; i < 400; ++i)
    {
        cycle();
        for (int k = 1; k < 8; ++k)
        {
            if (*aliveOut[k] != *aliveOut[0])
            {
                CHECK(0 && "all status messages carry the same alive counter");
                k = 8;
            }
        }
        CHECK(*aliveOut[0] >= 1U && *aliveOut[0] <= 14U);
        if (*aliveOut[0] != previous)
        {
            uint8 expected = (previous >= 14U) ? 1U : (uint8)(previous + 1U);
            CHECK(*aliveOut[0] == expected);
            ++steps;
            previous = *aliveOut[0];
        }
    }
    CHECK(steps == 40); /* once per 100 ms */
}

static void statusExtensionFrame(void)
{
    setpointFrame123(ENABLE_ON, 3.7, ENABLE_ON, 3.7, ENABLE_ON, 3.7);
    *controlQlf[5] = QLF_ERROR_TIMEOUT; /* 0x105 lost */
    *controlQlf[8] = QLF_DEBOUNCE;      /* 0x132 not yet received */
    SUPPLY(ISupply_mV) = 500U;
    SUPPLY(Limit)      = 1U;
    cycles(1500);
    CanDb_STATUS_BATTSIM_EXT_t msg;
    CanDb_STATUS_BATTSIM_EXT_Init(&msg);
    msg.ALIVE_STATUS_BATTSIM_EXT = MODE(AliveStatusBattSimExt);
    msg.BATTSIM_OVERLOAD         = SUPPLY(Overload);
    msg.BATTSIM_LIMIT            = SUPPLY(LimitActive);
    msg.BATTSIM_FAIL_REASON      = MODE(FailReason);
    msg.QLF_CONTROL_CELL01_02_03 = MODE(ValidCell010203);
    msg.QLF_CONTROL_CELL04_05_06 = MODE(ValidCell040506);
    msg.QLF_CONTROL_CELL07_08_09 = MODE(ValidCell070809);
    msg.QLF_CONTROL_CELL10_11_12 = MODE(ValidCell101112);
    msg.QLF_CONTROL_CELL13_14_15 = MODE(ValidCell131415);
    msg.QLF_CONTROL_CELL16       = MODE(ValidCell16);
    msg.QLF_CONTROL_BATTSIM      = MODE(ValidBattSim);
    msg.QLF_CONTROL_DYNCELLSIM1  = MODE(ValidDynCellSim1);
    msg.QLF_CONTROL_DYNCELLSIM2  = MODE(ValidDynCellSim2);
    msg.BATTSIM_SUPPLY_CURRENT   = CanDb_STATUS_BATTSIM_EXT_BATTSIM_SUPPLY_CURRENT_FromDouble(SUPPLY(SupplyCurrent_A));
    msg.FW_VERSION_MAJOR         = MODE(FwVersionMajor);
    msg.FW_VERSION_MINOR         = MODE(FwVersionMinor);
    msg.FW_VERSION_PATCH         = MODE(FwVersionPatch);
    uint8_t data[CANDB_STATUS_BATTSIM_EXT_LENGTH];
    CanDb_STATUS_BATTSIM_EXT_Pack(&msg, data);
    /* qualifier bits 12..20 in the order 0x100..0x105, 0x130, 0x131, 0x132: 0x105 (bit 17) and 0x132 (bit 20) are 0 */
    uint32_t bits = (uint32_t)data[1] | ((uint32_t)data[2] << 8U);
    CHECK(((bits >> 4U) & 0x1FFU) == 0x0DFU); /* bit i = qualifier i; i = 5 (0x105) and 8 (0x132) are 0 */
    CHECK((data[0] & 0x10U) == 0U);           /* no overload */
    CHECK((data[0] & 0x20U) != 0U);           /* LIMIT */
    CHECK((data[1] & 0x0FU) == 0U);           /* FAIL reason none */
    CHECK(data[5] == 0U && data[6] == 2U && data[7] == 0U); /* version 0.2.0 */
    uint16_t current = (uint16_t)(data[3] | (data[4] << 8U));
    CHECK(current > 480U && current < 510U);   /* 0.5 A in 0.001 A */
    *controlQlf[5] = QLF_OK;
    *controlQlf[8] = QLF_OK;
    SUPPLY(ISupply_mV) = 0U;
    SUPPLY(Limit)      = 0U;
    cycles(1000);
}

int main(void)
{
    BattSimMode_Init();
    startIsStandbyWithWatchdogReason();
    setpointFrameBecomesDuty();
    actualValueFollowsTheMeasurement();
    timeoutOfControlMessageSwitchesOffInTheSameStep();
    aliveErrorSwitchesOffAfterDebounce();
    lostControlMessageInStopIsNoFail();
    keysSwitchTheModes();
    remoteLedBlinksInFail();
    aliveCountsOneToFourteen();
    statusExtensionFrame();
    overloadIsFailAndNeedsLowCurrentToReset();
    printf("%d checks, %d failures\n", checks, failures);
    return (failures == 0) ? 0 : 1;
}
